import{_ as t,c as e,o as r,ae as n}from"./chunks/framework.Cd-3tpCq.js";const f=JSON.parse('{"title":"关于我们","description":"关于 MinecraftSounds 团队和项目的信息","frontmatter":{"title":"关于我们","description":"关于 MinecraftSounds 团队和项目的信息"},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),o={name:"about.md"};function i(l,a,s,c,u,h){return r(),e("div",null,a[0]||(a[0]=[n('<h1 id="关于-minecraftsounds" tabindex="-1">关于 MinecraftSounds <a class="header-anchor" href="#关于-minecraftsounds" aria-label="Permalink to &quot;关于 MinecraftSounds&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p>MinecraftSounds 音乐包生成器 是一款专为我的世界（Minecraft）玩家设计的音乐包生成工具，旨在让玩家能够轻松创建、管理和分享自定义的游戏音效和音乐。我们的目标是让每个人，无论是否有编程经验，都能够创建专业的音乐包。</p><h2 id="核心成员" tabindex="-1">核心成员 <a class="header-anchor" href="#核心成员" aria-label="Permalink to &quot;核心成员&quot;">​</a></h2><ul><li><strong>小阿狼是也</strong> - 项目负责人 &amp; 主程序员</li></ul><h2 id="项目历史" tabindex="-1">项目历史 <a class="header-anchor" href="#项目历史" aria-label="Permalink to &quot;项目历史&quot;">​</a></h2><p>MinecraftSounds 音乐包生成器 项目始于2025年8月月初，当时我们注意到许多玩家想要播放自己想听的音乐或音频，但苦于小白不会手动制作音乐包，也没有简单易用的工具。</p><p>耗时三天（2025年8月10日-2025年8月13日），由小阿狼是也开发，零一狼AL01出品的MinecraftSounds 音乐包生成器第一个测试版本诞生了。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p>MinecraftSounds 音乐包生成器 使用以下技术构建：</p><ul><li><strong>Python</strong> - 软件使用的编程语言</li><li><strong>PyQt5</strong> - 用于构建用户界面</li><li><strong>FFmpeg</strong> - 用于音频处理</li><li><strong>PyInstaller</strong> - 用于打包软件</li><li><strong>文档网站</strong>：VitePress</li></ul><h2 id="开源协议" tabindex="-1">开源协议 <a class="header-anchor" href="#开源协议" aria-label="Permalink to &quot;开源协议&quot;">​</a></h2><p>MinecraftSounds 音乐包生成器采用 GPL-2.0 开源许可证发布，这是一个自由且开放的软件许可协议。根据该协议，您可以自由地使用、研究、修改和分发本软件，但必须确保衍生作品同样采用 GPL-2.0 协议，并保留原始的版权声明和许可证信息。我们相信开源精神能够促进社区协作，推动项目持续发展。</p><h2 id="支持我们" tabindex="-1">支持我们 <a class="header-anchor" href="#支持我们" aria-label="Permalink to &quot;支持我们&quot;">​</a></h2><p>如果你喜欢 MinecraftSounds 音乐包生成器，可以通过以下方式支持我们：</p><ul><li>在 <a href="https://github.com/al01cn/MinecraftSounds" target="_blank" rel="noreferrer">GitHub</a> 上给项目点星</li><li>在 <a href="https://gitee.com/al01/minecraft-sounds" target="_blank" rel="noreferrer">Gitee</a> 上给项目点星</li><li>向你的朋友推荐我们的工具</li><li>报告 bug 或提交功能请求</li><li>贡献代码或文档</li></ul><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><ul><li><strong>GitHub</strong>：<a href="https://github.com/al01cn/MinecraftSounds" target="_blank" rel="noreferrer">github.com/al01cn/MinecraftSounds</a></li><li><strong>Gitee</strong>：<a href="https://gitee.com/al01/minecraft-sounds" target="_blank" rel="noreferrer">gitee.com/al01/minecraft-sounds</a></li><li><strong>电子邮件</strong>：<a href="mailto:contact@al01.cn" target="_blank" rel="noreferrer">contact@al01.cn</a></li></ul><h2 id="感谢" tabindex="-1">感谢 <a class="header-anchor" href="#感谢" aria-label="Permalink to &quot;感谢&quot;">​</a></h2><p>我们要感谢所有为 MinecraftSounds 项目做出贡献的开发者、测试者和用户。没有你们的支持，这个项目不可能成功。</p><p>特别感谢：</p><ul><li><strong>Mojang团队</strong> - 创造了这款精彩的游戏</li><li><strong>开源社区</strong> - 提供的各种优秀工具和库</li><li><strong>所有在测试阶段提供反馈的用户</strong> - 帮助我们改进和完善软件</li></ul>',22)]))}const g=t(o,[["render",i]]);export{f as __pageData,g as default};
